import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import ChangePasswordModal from './ChangePasswordModal';
import ScanModal from './ScanModal';
import DepartmentQRModal from './DepartmentQRModal';

export default function Navbar({ title, sub, greeting, notifCount = 0, dept_id, dept_name, onNotificationsClick }) {
  const { user, logout } = useAuth();
  const nav = useNavigate();
  const [showPw, setShowPw]     = useState(false);
  const [showScan, setShowScan] = useState(false);
  const [showDeptQR, setShowDeptQR] = useState(false);

  const doLogout = async () => { await logout(); nav('/login'); };

  return (
    <>
      <nav className="navbar">
        <div className="nb-brand">
          <img src="/logo-dashboard.png" alt="Logo" style={{ width:34, height:34, borderRadius:'50%', objectFit:'cover' }} />
          <div>
            <span className="nb-title">{title || 'QR Office'}</span>
            {greeting && <span className="nb-sub">👋 {greeting}</span>}
            {!greeting && sub && <span className="nb-sub">{sub}</span>}
          </div>
        </div>
        <div className="nb-actions">
          <button className="btn btn-ghost btn-sm" type="button" onClick={onNotificationsClick} style={{ position: 'relative' }}>
            🔔 Notifications
            {notifCount > 0 && (
              <span style={{
                position: 'absolute',
                top: '-4px',
                right: '-4px',
                background: '#dc2626',
                color: '#fff',
                borderRadius: '50%',
                width: '20px',
                height: '20px',
                fontSize: '11px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontWeight: '700'
              }}>
                {notifCount}
              </span>
            )}
          </button>
          {dept_id && dept_name && (
            <button className="btn btn-ghost btn-sm" onClick={() => setShowDeptQR(true)}>🏢 Department QR</button>
          )}
          <button className="btn btn-ghost btn-sm" onClick={() => setShowScan(true)}>📷 Scan</button>
          <button className="btn btn-ghost btn-sm" onClick={() => setShowPw(true)}>🔑 Password</button>
          <button className="btn btn-ghost btn-sm" onClick={doLogout}>⏻ Logout</button>
        </div>
      </nav>
      {showPw   && <ChangePasswordModal onClose={() => setShowPw(false)} />}
      {showScan && <ScanModal onClose={() => setShowScan(false)} />}
      {showDeptQR && <DepartmentQRModal dept_id={dept_id} dept_name={dept_name} onClose={() => setShowDeptQR(false)} />}
    </>
  );
}
